/**
 * Course goal data. GENERATED by transcribing the macOS course source
 * (leanring-buddy/ClickyCourse.swift → ClickyCourseCatalog.buildAWebsiteCourse) —
 * so these goals are identical to the Mac's, down to the wording of every
 * coachAsk and doneWhen.
 *
 * Transcribed directly from Swift rather than via Teachy.Engine/CourseDefinitions.cs:
 * the C# course definitions were not updated for the "Make a Website" rewrite and
 * are no longer a source of truth for this app. Do not hand-edit — change the
 * Swift source and re-transcribe.
 */

export interface CourseLearningGoal {
  id: string;
  title: string;
  goal: string;
  coachAsk: string;
  /** Natural-language completion criteria, checked by vision. Null = concept goal
   *  that advances on learner confirmation (the Mac's advanceOnUserConfirm). */
  doneWhen: string | null;
  outcome: string;
  /** Soft teach-back asked after the goal passes (protégé effect). Null when the
   *  Mac goal sets skipTeachBack — the flagship keeps momentum instead. */
  teachBackPrompt: string | null;
  tips: string[];
}

